<?php require 'config.php';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){$u=trim($_POST['username']??'');$p=$_POST['password']??'';$c=$_POST['confirm_password']??'';$users=read_data('users');if(strlen($u)<3)$errors[]='Username minimal 3 karakter.';elseif(strlen($p)<6)$errors[]='Password minimal 6 karakter.';elseif($p!==$c)$errors[]='Konfirmasi password tidak cocok.';elseif(array_filter($users,fn($x)=>strcasecmp($x['username'],$u)===0))$errors[]='Username sudah digunakan.';else{$users[]=['id'=>next_id($users),'username'=>$u,'password'=>password_hash($p,PASSWORD_DEFAULT),'created_at'=>date('Y-m-d H:i:s')];write_data('users',$users);$_SESSION['flash']=['type'=>'success','message'=>'Akun berhasil dibuat. Silakan login.'];redirect('login.php');}}?><!doctype html><html lang="id"><head> <link rel="icon" href="assets/img/logo.png"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="assets/css/style.css"><title>Daftar</title></head><body><div class="auth-wrapper"><div class="auth-card"><div class="auth-brand"><img src="assets/img/logo.png" alt="Logo" style="height:64px;display:block;margin:0 auto 8px">NetStock</div><h1>Daftar Akun</h1><?php foreach($errors as $e1):?><div class="alert alert-error"><?=e($e1)?></div><?php endforeach;?><form method="post"><div class="form-group"><label>Username</label><input name="username" required></div><div class="form-group"><label>Password</label><input type="password" name="password" required></div><div class="form-group"><label>Konfirmasi Password</label><input type="password" name="confirm_password" required></div><button class="btn btn-primary" style="width:100%">Daftar</button></form><p class="auth-switch">Sudah punya akun? <a href="login.php">Login</a></p></div></div></body></html>